import{_ as t,o as d,c as a,a6 as s}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"子代理","description":"Codex CLI 的子代理（subagent）用法，涵盖触发与切换、并发与汇总、自定义 agent 文件与 agents 配置，以及 codex agents 代理总览。","frontmatter":{"title":"子代理","description":"Codex CLI 的子代理（subagent）用法，涵盖触发与切换、并发与汇总、自定义 agent 文件与 agents 配置，以及 codex agents 代理总览。","source":"https://daiw.org/manual/codex/subagents"},"headers":[],"relativePath":"manual/agent/codex/subagents.md","filePath":"manual/agent/codex/subagents.md"}'),o={name:"manual/agent/codex/subagents.md"};function n(i,e,c,r,l,p){return d(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="子代理" tabindex="-1">子代理 <a class="header-anchor" href="#子代理" aria-label="Permalink to &quot;子代理&quot;">​</a></h1><blockquote><p>Codex CLI 的子代理（subagent）用法，涵盖触发与切换、并发与汇总、自定义 agent 文件与 agents 配置，以及 codex agents 代理总览。</p></blockquote><p>子代理（subagent）是 Codex 为子任务派生出来的独立 agent：它在自己的线程里完成模型调用和工具调用，主代理等它们结束后把结果汇总成一次回复。中间输出留在子线程里，主线程只保留需求、决策和结论。</p><p>当前版本默认启用子代理，CLI、桌面端和 IDE 扩展都能看到子代理的活动。每个子代理都要单独调用模型和工具，所以同样的任务，用子代理比单代理消耗更多 token。</p><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to &quot;什么时候用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>适合</th><th>需要谨慎</th></tr></thead><tbody><tr><td>代码库探索、只读扫描、问题分诊</td><td>多个 agent 同时改代码（容易冲突，协调成本高）</td></tr><tr><td>从多个角度评审同一个分支</td><td>步骤之间强依赖、拆不开的任务</td></tr><tr><td>跑测试、分析日志、总结长文档</td><td>对 token 成本敏感的场景</td></tr></tbody></table><p>确实要多个 agent 并行写代码时，给每个 agent 明确划分负责的文件或模块。</p><h2 id="在-cli-里使用" tabindex="-1">在 CLI 里使用 <a class="header-anchor" href="#在-cli-里使用" aria-label="Permalink to &quot;在 CLI 里使用&quot;">​</a></h2><h3 id="触发" tabindex="-1">触发 <a class="header-anchor" href="#触发" aria-label="Permalink to &quot;触发&quot;">​</a></h3><p>默认情况下，本地 Codex 不会自作主张地派生子代理，只在两种情况下委派：</p><ul><li>你直接提出，例如“派两个子代理”“把这些工作并行委派出去”“每一点派一个 agent”；</li><li>适用的 <code>AGENTS.md</code> 或技能指令要求委派。</li></ul><p>例外是使用 V2 多代理实现（见下文）且推理强度为 <code>ultra</code> 时：Codex 会收到“可以主动委派”的提示，在并行能节省时间或提高质量时自行派生子代理；你在对话里的明确要求仍然优先。</p><p>好的委派提示要说清三件事：怎么拆分、是否等所有子代理完成再继续、每个子代理返回什么。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用并行子代理评审这个分支：一个查安全风险，一个查测试缺口，一个看可维护性。</span></span>
<span class="line"><span>三个都完成后，按类别汇总问题，并附上文件引用。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="编排与汇总" tabindex="-1">编排与汇总 <a class="header-anchor" href="#编排与汇总" aria-label="Permalink to &quot;编排与汇总&quot;">​</a></h3><p>派生、转发后续指令、等待结果、关闭线程都由 Codex 负责。同时运行多个子代理时，Codex 会等所有请求的结果到齐，再给出一份汇总回复。运行过程中，你可以直接让 Codex 引导（steer）某个子代理、停掉它，或者关闭已完成的线程。</p><h3 id="查看与切换" tabindex="-1">查看与切换 <a class="header-anchor" href="#查看与切换" aria-label="Permalink to &quot;查看与切换&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/subagents</code></td><td>在本会话的子代理线程之间切换，查看某个线程的进展</td></tr><tr><td><code>/agents</code></td><td>打开代理总览，浏览、筛选共享后台服务上的所有 agent 会话（见下文）</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>官方文档把切换线程的命令写作 <code>/agent</code>；v0.167.0 CLI 里注册的是 <code>/subagents</code>（本会话的子代理）和 <code>/agents</code>（代理总览），没有单独的 <code>/agent</code>。</p></div><h3 id="审批与沙箱" tabindex="-1">审批与沙箱 <a class="header-anchor" href="#审批与沙箱" aria-label="Permalink to &quot;审批与沙箱&quot;">​</a></h3><ul><li>交互模式下，非当前线程的审批请求也会弹出，覆盖层会标出来源线程；按 <code>o</code> 可以先打开那个线程，再批准、拒绝或回答。</li><li>非交互运行（例如 <code>codex exec</code>），或者当前无法弹出新审批时，需要新审批的操作会直接失败，错误交回给父工作流。</li><li>v0.156.0 起，子代理也可以发起 MCP elicitation（如浏览器登录、表单输入），按当前的审批策略与自动审查规则交给你处理；请求安装插件则只允许主线程发起。</li><li>子代理的沙箱、审批策略、审批审查方式与工作目录都跟随父轮次当前的设置，包括父轮次在运行时改过的部分（例如用 <code>/permissions</code> 调整的权限、<code>--yolo</code>）。自定义 agent 文件改不了这些设置，写了 <code>sandbox_mode</code>、<code>approval_policy</code> 也不生效（见下文“文件位置与字段”）。</li></ul><h2 id="并发与嵌套" tabindex="-1">并发与嵌套 <a class="header-anchor" href="#并发与嵌套" aria-label="Permalink to &quot;并发与嵌套&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>配置键</th><th>默认值</th></tr></thead><tbody><tr><td>同时打开的子代理线程（不含主线程）</td><td><code>agents.max_concurrent_threads_per_session</code></td><td>由多代理实现决定，见下</td></tr><tr><td>嵌套深度</td><td><code>agents.max_depth</code></td><td><code>1</code>，即子代理不能再派生下一层；只对 V1 实现生效</td></tr></tbody></table><p>Codex 有两套多代理实现，用哪一套由模型元数据决定：v0.167.0 的模型目录中，默认模型 <code>gpt-6.1-sol</code> 与 <code>gpt-6.1-terra</code>、<code>gpt-6-astra</code>、<code>gpt-6-sol</code> 等默认标记为 V2（<code>multi_agent_version = &quot;v2&quot;</code>，默认子代理推理强度为 <code>xhigh</code>）；模型的具体 V1/V2 标记与服务端目录可能变化，可以在 CLI 的 <code>/model</code> 与 <code>codex debug models</code> 中核对。<code>features.multi_agent_v2 = true</code> 可以固定使用 V2（v0.161.0 起 Amazon Bedrock 提供方也支持 <code>multi_agent_v2</code> 的路径寻址多代理工作流）。不设上限时，源码默认值是 V2 上限为 3 个子代理（连同主线程共 4 个线程），V1 上限为 6 个。V2 的上限也可以写在 <code>[features.multi_agent_v2]</code> 表里的 <code>max_concurrent_threads_per_session</code>（写成表时用 <code>enabled = true</code> 固定使用 V2），这个数连同主线程一起算，并且优先于 <code>agents.max_concurrent_threads_per_session</code>。</p><p>v0.158.0 起，<code>[features.multi_agent_v2]</code> 新增 <code>disable_direct_message</code>（默认 <code>false</code>）：设为 <code>true</code> 后，V2 不再提供 agent 之间直接发消息的工具（<code>send_message</code>、<code>followup_task</code>），派生子代理、子代理结果的自动回传和其他管理工具不受影响。它要求当前会话里有可用的 agent 留言板（仍在开发中的 <code>features.agent_message_board</code>），否则这一轮会直接报错，所以目前只在试用留言板时才用得上。</p><h2 id="模型与推理强度" tabindex="-1">模型与推理强度 <a class="header-anchor" href="#模型与推理强度" aria-label="Permalink to &quot;模型与推理强度&quot;">​</a></h2><p>不做任何配置时，子代理沿用父代理的模型和推理强度。需要区分时，按以下规则解析：</p><ol><li>自定义 agent 文件里写了 <code>model</code> 或 <code>model_reasoning_effort</code>，以文件为准；</li><li>否则依次取：派生请求里显式指定的值 → <code>[agents]</code> 里的默认值 → 父代理的值；</li><li>只选了模型、没给推理强度时，使用该模型的默认强度；自定义 agent 文件只写 <code>model</code> 时，沿用前面解析出的强度，新模型不支持这个强度的话，就在文件里一并写上 <code>model_reasoning_effort</code>。</li></ol><p>探索类任务可以用更快、更便宜的模型，评审、安全审查可以用更高的推理强度，详见<a href="/Front2Full/manual/agent/codex/models">模型与推理</a>。</p><h2 id="自定义-agent" tabindex="-1">自定义 agent <a class="header-anchor" href="#自定义-agent" aria-label="Permalink to &quot;自定义 agent&quot;">​</a></h2><h3 id="内置-agent" tabindex="-1">内置 agent <a class="header-anchor" href="#内置-agent" aria-label="Permalink to &quot;内置 agent&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>用途</th></tr></thead><tbody><tr><td><code>default</code></td><td>通用的兜底 agent</td></tr><tr><td><code>worker</code></td><td>执行型：实现功能的一部分、修测试或 bug、拆分大型重构</td></tr><tr><td><code>explorer</code></td><td>读为主的代码库探索，回答具体、范围明确的问题</td></tr></tbody></table><p>这三个内置角色只有说明文字，不改模型、权限或其他设置。只有在你定义了至少一个自定义 agent 时，派生子代理的工具才会带上 <code>agent_type</code> 参数，模型这时才能按名字选用角色（内置角色也会一并列出）；没有自定义 agent 时，子代理一律按 <code>default</code> 派生。自定义 agent 与内置 agent 同名（例如也叫 <code>explorer</code>）时，以自定义的为准。</p><h3 id="文件位置与字段" tabindex="-1">文件位置与字段 <a class="header-anchor" href="#文件位置与字段" aria-label="Permalink to &quot;文件位置与字段&quot;">​</a></h3><p>每个 TOML 文件定义一个 agent，个人的放在 <code>~/.codex/agents/</code>，项目级的放在 <code>.codex/agents/</code>（可以提交到仓库）。Codex 递归查找这些目录下的 <code>*.toml</code> 文件。agent 文件的写法与 <code>config.toml</code> 相同，但派生时只有下表列出的设置会生效：它只能定制子代理的指令、模型与输出风格，或者收窄它的能力，不能扩大父会话的权限。</p><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>是</td><td>派生或引用时使用的名字；以此字段为准，文件名与它一致更省事</td></tr><tr><td><code>description</code></td><td>是</td><td>告诉 Codex 什么时候该用这个 agent</td></tr><tr><td><code>developer_instructions</code></td><td>是</td><td>定义行为的核心指令</td></tr><tr><td><code>nickname_candidates</code></td><td>否</td><td>派生出的 agent 可用的昵称；只能含 ASCII 字母、数字、空格、<code>-</code> 和 <code>_</code>，不能重复</td></tr><tr><td><code>model</code>、<code>model_reasoning_effort</code>、<code>model_reasoning_summary</code>、<code>model_verbosity</code>、<code>personality</code>、<code>service_tier</code></td><td>否</td><td>子代理使用的模型、推理与输出设置；省略时按下文“模型与推理强度”的规则继承</td></tr><tr><td><code>[features]</code></td><td>否</td><td>只能关闭 <code>shell_tool</code>、<code>apps</code>、<code>plugins</code>、<code>memories</code>、<code>request_permissions_tool</code> 这几项能力；写成 <code>true</code> 或写其他开关都不生效</td></tr><tr><td><code>[skills]</code></td><td>否</td><td>只能停用技能：<code>skills.config</code> 中 <code>enabled = false</code> 的条目、<code>skills.bundled.enabled = false</code>、<code>skills.include_instructions = false</code></td></tr></tbody></table><p>除此之外的键（如 <code>sandbox_mode</code>、<code>approval_policy</code>、<code>mcp_servers</code>、<code>model_provider</code>、<code>notify</code>）写了也不生效：子代理的沙箱、审批与工作目录跟随父轮次，MCP 服务器、模型提供方等沿用父会话的配置。需要专用的 MCP 服务器，就把它配置在主配置里，再在 agent 的指令里说明该用哪个。</p><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><p><code>.codex/agents/reviewer.toml</code>：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;reviewer&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PR 评审：关注正确性、安全和缺失的测试。&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model_reasoning_effort = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;high&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">developer_instructions = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">像代码负责人一样评审。</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">优先看正确性、安全、行为回归和缺失的测试。</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">先列具体问题，尽量附复现步骤；不要只提风格意见。</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><code>.codex/agents/docs-researcher.toml</code>（只做调研，关掉 shell 工具）：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;docs_researcher&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;文档专家：通过文档 MCP 服务器核实 API 与框架行为。&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">developer_instructions = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">用 openaiDeveloperDocs 这个 MCP 服务器确认 API、选项和特定版本的行为。</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">回答简洁，附上链接或准确出处。不要修改代码。</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">features</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">shell_tool = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # agent 文件只能关掉能力，不能打开</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>这里用到的 <code>openaiDeveloperDocs</code> 要事先配置在 <code>~/.codex/config.toml</code> 的 <code>[mcp_servers]</code> 里，子代理沿用父会话的 MCP 服务器。</p><p>之后在提示里点名即可，例如“让 reviewer 找出真实风险，让 docs_researcher 核实补丁依赖的框架 API”。</p><p>也可以在 <code>config.toml</code> 里声明角色，把配置放进单独的文件（相对路径相对于声明它的那个配置文件解析）：</p><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">researcher</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;偏重调研的角色。&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config_file = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./agents/researcher.toml&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nickname_candidates = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Herodotus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ibn Battuta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>[agents]</code> 下的标量设置名（如 <code>enabled</code>）是保留字，不能用作角色名。</p><h2 id="全局设置-agents" tabindex="-1">全局设置：[agents] <a class="header-anchor" href="#全局设置-agents" aria-label="Permalink to &quot;全局设置：[agents]&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>agents.enabled</code></td><td><code>true</code></td><td>设为 <code>false</code> 关闭多代理工具；显式开启的 <code>features.multi_agent_v2</code> 优先于它</td></tr><tr><td><code>agents.max_concurrent_threads_per_session</code></td><td>由实现决定</td><td>同时打开的子代理线程上限，不含主线程，下限为 <code>1</code>；旧名 <code>agents.max_threads</code> 仍然可用，同一层配置里两者都写时以新名为准</td></tr><tr><td><code>agents.max_depth</code></td><td><code>1</code></td><td>嵌套深度，只对 V1 实现生效</td></tr><tr><td><code>agents.default_subagent_model</code></td><td>未设置</td><td>子代理的默认模型，派生时显式指定的模型优先</td></tr><tr><td><code>agents.default_subagent_reasoning_effort</code></td><td>未设置</td><td>子代理的默认推理强度，派生时显式指定的值优先</td></tr><tr><td><code>agents.interrupt_message</code></td><td><code>true</code></td><td>agent 的轮次被中断时，是否在它的上下文里记一条模型可见的消息</td></tr></tbody></table><div class="language-toml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">agents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">max_concurrent_threads_per_session = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">default_subagent_reasoning_effort = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;medium&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="codex-agents-代理总览" tabindex="-1">codex agents：代理总览 <a class="header-anchor" href="#codex-agents-代理总览" aria-label="Permalink to &quot;codex agents：代理总览&quot;">​</a></h2><p><code>codex agents</code> 打开代理总览，浏览所有 agent 会话及其子代理、查看实时任务详情并恢复会话。TUI 里的 <code>/agents</code> 打开的是同一个视图；输入框为空时按 <code>←</code> 也能打开（前提是编辑器的左移键仍是 <code>←</code>，底部会有提示）。v0.156.0 起它在界面上改称 agent command center；v0.167.0 起，除了共享的后台守护进程或远程 app server 外，内嵌 app server 模式（<code>--no-daemon</code>）下也可以直接使用 <code>codex agents</code> 与 <code>/agents</code> 浏览和管理本地会话。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>--remote ADDR</code></td><td>连接远程 app server，支持 <code>ws://host:port</code>、<code>wss://host:port</code>、<code>unix://</code>、<code>unix://PATH</code></td></tr><tr><td><code>--remote-auth-token-env ENV_VAR</code></td><td>保存 WebSocket bearer token 的环境变量名；只能配合 <code>wss://</code> 或回环地址的 <code>ws://</code></td></tr><tr><td><code>-C, --cd DIR</code></td><td>在远程服务器上新建任务时使用的目录</td></tr><tr><td><code>--no-daemon</code></td><td>不连接也不启动共享后台服务，在内嵌 app server 上打开代理总览（v0.167.0 起支持，不能与 <code>--remote</code> 同用）</td></tr><tr><td><code>--no-alt-screen</code></td><td>不使用终端的备用屏幕</td></tr></tbody></table><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 默认连接或自动拉起本机后台服务</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-daemon</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 内嵌模式下浏览本地会话</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>总览顶部按状态分成 All、Needs you、Working、Ready、Inactive 几个标签，标签上带任务数；任务可以按项目、目录（v0.165.0 起支持按目录分组，并将托管 Git worktree 归入所属仓库之下）、状态或模型分组，且所选分组方式在下次启动时会保留（v0.162.0 起）。后台任务产生尚未查看的新结果时会显示未读标记（v0.167.0 起）。选中任务后，详情里显示所用模型、输入与输出 token 数，Business 与 Enterprise 套餐还会显示估算的 credits 与美元费用。启动时除了已加载的会话，还会列出近期的 10 个会话。</p><p>v0.156.0 起的默认按键如下。除导航键外，它们对应 <code>tui.keymap.agents</code> 下的 <code>new_task</code>、<code>new_worktree</code>、<code>resume</code>、<code>search</code>、<code>fork</code>、<code>pin</code>、<code>rename</code>、<code>stop</code>、<code>archive</code>、<code>hide</code>、<code>delete</code>、<code>toggle_grouping</code>，可以重新绑定；按 <code>?</code> 随时查看当前生效的按键：</p><table tabindex="0"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><code>↑</code>、<code>↓</code>、<code>PgUp</code>、<code>PgDn</code></td><td>在任务列表中移动、翻页</td></tr><tr><td><code>Enter</code></td><td>打开选中的任务</td></tr><tr><td><code>Tab</code>、<code>Shift+Tab</code></td><td>在状态标签之间切换</td></tr><tr><td><code>n</code></td><td>新开一个会话（按项目分组时，放在选中任务所在的检出里）；v0.158.0 起，会话建好之前输入框一直可见、可以先输入，不再被清掉或换成 Loading task 画面</td></tr><tr><td><code>w</code></td><td>从项目的默认分支新建 worktree 并在其中开一个空白会话（优先用远端的 <code>HEAD</code>，找不到时用 <code>main</code> 或 <code>master</code>，不会先 fetch）</td></tr><tr><td><code>o</code></td><td>打开会话恢复选择器</td></tr><tr><td><code>f</code></td><td>将选中的任务分叉（fork）为新会话（v0.161.0 起）</td></tr><tr><td><code>p</code></td><td>置顶或取消置顶选中的任务（v0.162.0 起）</td></tr><tr><td><code>r</code>、<code>x</code></td><td>重命名选中的任务；停止正在运行的任务</td></tr><tr><td><code>g</code></td><td>在按项目、按目录、按状态、按模型分组之间切换（v0.162.0 起跨启动记住选择）</td></tr><tr><td><code>h</code></td><td>隐藏选中的任务但不停止它，直到你再次恢复它或重启 TUI</td></tr><tr><td><code>a</code></td><td>归档选中的任务及其子代理，需确认（v0.166.0 起取消归档父会话时会一并恢复这些派生的子代理线程）</td></tr><tr><td><code>Backspace</code></td><td>永久删除选中的任务及其子代理的记录，需确认</td></tr><tr><td><code>?</code></td><td>显示全部按键</td></tr><tr><td><code>Esc</code></td><td>关闭帮助，或取消搜索、重命名；再按一次离开总览</td></tr></tbody></table><p>v0.155.0 的默认键是 <code>Ctrl+N</code>、<code>Ctrl+E</code>、<code>Ctrl+W</code> 这类组合键以及 <code>Delete</code>，v0.156.0 起统一改成上表的单个按键；在 <code>tui.keymap.agents</code> 里自定义过的，以你的配置为准。</p><ul><li>由另一个 app server 管理的任务（例如正在桌面应用里打开的对话）会以只读历史打开：按 <code>r</code> 重试接管，v0.157.0 起按 <code>f</code> 可以分叉出一个可编辑的副本继续，按 <code>Esc</code> 回到总览（v0.158.0 起也可以按 <code>←</code>，草稿保留）。</li><li>连接守护进程或远程 app server 时，在会话里执行 <code>/archive</code>（v0.155.0 起）或 <code>/delete</code>（v0.156.0 起）之后都会回到这个总览。v0.157.0 起，正在进行语音对话的任务带有 <code>voice</code> 标记。</li><li><code>codex agents</code> 不接受初始提示词或图片。连接远程服务器时，不能再带 <code>--oss</code> 之类的本地模型提供方参数或 <code>--add-dir</code>；工作负载身份（workload identity）生效时不可用。</li></ul><p>守护进程的管理见 <a href="/Front2Full/manual/agent/codex/sdk-app-server">SDK 与 App Server</a>。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ol><li><strong>成本</strong>：子代理越多，token 消耗越多；嵌套子代理的用量也计入根目标（<code>/goal</code>）的 token 预算（v0.151.0 起）。</li><li><strong>项目级 agent 需要信任</strong>：未受信任的项目会跳过项目级的 <code>.codex/</code> 配置层，其中的 <code>.codex/agents/</code> 也不会加载。</li><li><strong>非交互运行没有审批弹窗</strong>：<code>codex exec</code> 里需要新审批的子代理操作会失败，事先用沙箱和审批设置放行必要的操作（见<a href="/Front2Full/manual/agent/codex/sandbox-approvals">沙箱、审批与安全</a>）。</li></ol>`,62)])])}const u=t(o,[["render",n]]);export{g as __pageData,u as default};
